def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1

    for i in range(n):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            if topmost_carpet == -1 or i > topmost_carpet:
                topmost_carpet = i

    return topmost_carpet

