def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    :param n: The highest degree of the polynomial.
    :param coeffs: A list of coefficients, starting with the coefficient of the highest degree term.
    :return: The string representation of the polynomial.
    """
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        if i == 0:
            term = str(abs(coeff))
        elif i == 1:
            if abs(coeff) == 1:
                term = 'x' if coeff == 1 else '-x'
            else:
                term = f'{abs(coeff)}x'
        else:
            if abs(coeff) == 1:
                term = f'x^{i}' if coeff == 1 else f'-x^{i}'
            else:
                term = f'{abs(coeff)}x^{i}'
        if coeff < 0:
            term = '-' + term
        terms.append(term)
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping and mapping[e] != o:
            return "Failed"
        mapping[e] = o

    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    This function takes a potential criminal's name (scenario) and a set of liars (liar_count) and checks if
    the statements made by all participants are consistent with this scenario, disregarding any statements
    about the day of the week.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    for participant, participant_statements in statements.items():
        for statement in participant_statements:
            if "day of the week" in statement:
                continue
            if participant in liar_count:
                if statement.startswith(scenario):
                    return False
            else:
                if not statement.startswith(scenario):
                    return False
    return True

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(min(j, a[i - 1]) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Find the maximum height position
    max_height_index = heights.index(max(heights))

    # Calculate the number of students to remove before the maximum height position
    left_remove = 0
    for i in range(max_height_index):
        if heights[i] >= heights[i + 1]:
            left_remove += 1

    # Calculate the number of students to remove after the maximum height position
    right_remove = 0
    for i in range(max_height_index, n - 1):
        if heights[i] <= heights[i + 1]:
            right_remove += 1

    # The total number of students to remove is the sum of left and right removals
    return left_remove + right_remove
